CREATE POLICY "Anyone can view store images" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'store-images');
CREATE POLICY "Admins can upload store images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'store-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins can update store images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'store-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins can delete store images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'store-images' AND public.has_role(auth.uid(),'admin'));